SELECT n.id, n.title
FROM note_link l
JOIN note n ON n.id = l.source_note_id
WHERE l.user_id = #{userId}
  AND l.target_note_id = #{noteId}
  AND n.user_id = #{userId}
  AND n.is_deleted = FALSE
ORDER BY n.updated_at DESC

